using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckSkyTow.Editor {
public static class SkyTowPresentationAuthoring {
 public static void Upgrade(){EditorSceneManager.OpenScene(SkyTowAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<SkyTowMatch>();Install(m);EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
 public static void Install(SkyTowMatch m){var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckFishing/Materials/Clear fishing river.mat");if(source==null)throw new InvalidOperationException("Verified Fishing URP water is required.");string path="Assets/TruckSkyTow/Materials/Arctic URP water.mat";var water=AssetDatabase.LoadAssetAtPath<Material>(path);if(water==null){water=UnityEngine.Object.Instantiate(source);water.name="Arctic animated URP water";water.color=new Color(.025f,.2f,.32f,.8f);water.SetTextureScale("_BumpMap",new Vector2(130,190));water.mainTextureScale=new Vector2(130,190);AssetDatabase.CreateAsset(water,path);}var surface=m.course.water.GetComponent<Renderer>();surface.sharedMaterial=water;if(surface.GetComponent<LWS.TruckFishing.FishingWaterFlow>()==null)surface.gameObject.AddComponent<LWS.TruckFishing.FishingWaterFlow>();var snow=m.GetComponent<SportsSnowSurface>();if(snow==null)throw new InvalidOperationException("Shared Weatherade/Taxi snow adapter required.");snow.permanentCoverage=.72f;
  var terrain=m.course.terrain;var ice=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/NWH/Common/TerrainLayers/IceLayer.terrainlayer");if(ice==null)throw new InvalidOperationException("Installed NWH ice terrain foundation missing.");string layerPath="Assets/TruckSkyTow/Art/Arctic ice crust.terrainlayer";var crust=AssetDatabase.LoadAssetAtPath<TerrainLayer>(layerPath);if(crust==null){crust=UnityEngine.Object.Instantiate(ice);crust.name="Arctic ice crust";crust.tileSize=Vector2.one*24;AssetDatabase.CreateAsset(crust,layerPath);}var rock=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/TruckSkyTow/Art/Arctic terrain layer.terrainlayer");terrain.terrainData.terrainLayers=new[]{crust,rock};int res=terrain.terrainData.alphamapResolution;var weights=new float[res,res,2];for(int z=0;z<res;z++)for(int x=0;x<res;x++){float u=x/(float)(res-1),v=z/(float)(res-1);float slope=terrain.terrainData.GetSteepness(u,v);float rocky=Mathf.Clamp01((slope-28)/28)*.75f;weights[z,x,0]=1-rocky;weights[z,x,1]=rocky;}terrain.terrainData.SetAlphamaps(0,0,weights);EditorUtility.SetDirty(terrain.terrainData);
  var cloth=SportsEventAuthoring.Mat("TruckSkyTow","Tow sail woven safety coral",new Color(.9f,.17f,.06f),.12f);cloth.SetFloat("_Cull",0);foreach(var r in m.racers){var sail=r.truck.transform.Find("Functional aerodynamic tow sail");var mesh=sail.GetComponent<MeshFilter>().sharedMesh;if(mesh.bounds.size.x>8){var vertices=mesh.vertices;for(int vertex=0;vertex<vertices.Length;vertex++)vertices[vertex].x*=.6f;mesh.vertices=vertices;mesh.RecalculateBounds();}var triangles=new int[72];for(int x=0;x<12;x++){int a=x*2;triangles[x*6]=a;triangles[x*6+1]=a+1;triangles[x*6+2]=a+2;triangles[x*6+3]=a+1;triangles[x*6+4]=a+3;triangles[x*6+5]=a+2;}mesh.triangles=triangles;mesh.RecalculateNormals();EditorUtility.SetDirty(mesh);sail.GetComponent<Renderer>().sharedMaterial=cloth;}
  var cameras=m.views.views.Select(v=>v.view).Concat(new[]{m.views.broadcast.view}).ToArray();foreach(var camera in cameras)camera.clearFlags=CameraClearFlags.Skybox;SportsScenicGradeAuthoring.Install(m.gameObject,cameras,"TruckSkyTow",-.35f);if(m.towEngine==null){m.towEngine=m.gameObject.AddComponent<AudioSource>();m.towEngine.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/NWH/Vehicle Physics 2/Sound/Engine/Running/EngineRunning - Truck4.wav");m.towEngine.loop=true;m.towEngine.playOnAwake=false;m.towEngine.spatialBlend=0;}SkyTowReviewAuthoring.Install(m);EditorUtility.SetDirty(m);EditorUtility.SetDirty(snow);}
}
}
